<!doctype html><html lang="en"><head><meta charset="utf-8"><title><?= e($estimate['estimate_no']) ?> - <?= e($s['garage_name']) ?></title><style>*{box-sizing:border-box}body{margin:0;background:#eef1f5;color:#172b4d;font:12px Arial,sans-serif}.toolbar{display:flex;justify-content:space-between;max-width:210mm;margin:16px auto;padding:10px 14px;background:#fff;border:1px solid #d0d5dd}.toolbar a,.toolbar button{padding:8px 12px;border:0;border-radius:4px;text-decoration:none;cursor:pointer;background:#f2f4f7;color:#172b4d}.toolbar button{background:#dc3545;color:#fff}.paper{width:210mm;min-height:297mm;margin:auto;padding:14mm;background:#fff;box-shadow:0 2px 12px #98a2b355}.brand{text-align:center;border-bottom:2px solid #172b4d;padding-bottom:10px}.brand h1{margin:0;text-transform:uppercase;color:#092b52;font-size:24px}.brand p,.brand small{display:block;margin:4px 0;color:#475467}.brand img{display:block;max-width:90px;max-height:55px;margin:0 auto 8px}.title{text-align:center;padding:15px 0 10px}.title h2{margin:0;color:#092b52;font-size:21px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:0 28px;border-block:1px solid #d0d5dd;padding:8px 0}.meta div{display:flex;justify-content:space-between;border-bottom:1px solid #eaecf0;padding:6px 0}.meta span{color:#475467}.meta strong{text-align:right;color:#101828}.section{margin-top:15px}.section h3{margin:0;padding:8px 10px;color:#fff;background:#092b52;font-size:12px}.section table{width:100%;border-collapse:collapse}.section th,.section td{border:1px solid #d0d5dd;padding:8px}.section th{color:#fff;background:#173b5e}.section th:not(:nth-child(2)),.section td:not(:nth-child(2)){text-align:right}.totals{width:55%;margin:15px 0 0 auto}.totals div{display:flex;justify-content:space-between;border-bottom:1px solid #eaecf0;padding:7px}.totals .grand{border-top:2px solid #092b52;border-bottom:0;color:#155eef;font-size:16px;font-weight:bold}.notes{margin-top:15px;padding:10px;border:1px solid #d0d5dd;white-space:pre-line}.footer{margin-top:24px;padding-top:12px;border-top:1px dashed #98a2b3;text-align:center;white-space:pre-line}.powered-by-print{font-size:10px;color:#667085!important}@page{size:A4;margin:0}@media print{body{background:#fff}.toolbar{display:none}.paper{width:210mm;min-height:297mm;margin:0;padding:14mm;box-shadow:none}}</style></head><body><div class="toolbar"><a href="index.php?page=admin&amp;section=estimates">Back to Estimates</a><span><a href="index.php?page=admin&amp;section=estimates-print-settings">Edit Header / Footer</a> <button onclick="window.print()">Print A4 Estimate</button></span></div><main class="paper"><header class="brand"><?php if($logo): ?><img src="<?= e($logo) ?>" alt="<?= e($s['garage_name']) ?> logo"><?php endif; ?><h1><?= e($s['garage_name']) ?></h1><?php if($s['tagline']): ?><p><?= e($s['tagline']) ?></p><?php endif; ?><?php if($s['address']): ?><small><?= nl2br(e($s['address'])) ?></small><?php endif; ?><?php if($s['contact_number']): ?><small><?= e($s['contact_number']) ?></small><?php endif; ?><?php if($s['secondary_contact_number']): ?><small><?= e($s['secondary_contact_number']) ?></small><?php endif; ?><?php if($s['email']): ?><small><?= e($s['email']) ?></small><?php endif; ?></header><?php if($s['receipt_header']): ?><div class="notes"><?= nl2br(e($s['receipt_header'])) ?></div><?php endif; ?><div class="title"><h2>ESTIMATE</h2></div><section class="meta"><div><span>Estimate No.</span><strong><?= e($estimate['estimate_no']) ?></strong></div><div><span>Estimate Date</span><strong><?= e($estimate['estimate_date']) ?></strong></div><div><span>Customer</span><strong><?= e($estimate['customer_name']) ?></strong></div><div><span>Valid Until</span><strong><?= e($estimate['valid_until']) ?></strong></div><div><span>Contact</span><strong><?= e($estimate['contact_number']) ?></strong></div><div><span>Vehicle</span><strong><?= e($estimate['vehicle_number']?:'-') ?></strong></div><div><span>Service / Issue</span><strong><?= e($estimate['service_type']) ?></strong></div><div><span>Mileage</span><strong><?= $estimate['mileage']!==null?e(number_format((float)$estimate['mileage'],2).' KM'):'-' ?></strong></div></section><section class="section"><h3>Estimate Items</h3><table><thead><tr><th>#</th><th>Description</th><th>Qty</th><th>Amount (Rs.)</th></tr></thead><tbody><?php foreach($estimate['items'] as $index=>$item): ?><tr><td><?= $index+1 ?></td><td><?= e($item['item_name']) ?></td><td><?= number_format((float)$item['quantity'],2) ?></td><td><?= number_format((float)$item['amount'],2) ?></td></tr><?php endforeach; ?></tbody></table></section><div class="totals"><div><span>Parts / Items</span><strong>Rs. <?= number_format((float)$estimate['subtotal']-(float)$estimate['service_charge'],2) ?></strong></div><div><span>Service Charge</span><strong>Rs. <?= number_format((float)$estimate['service_charge'],2) ?></strong></div><div><span>Subtotal</span><strong>Rs. <?= number_format((float)$estimate['subtotal'],2) ?></strong></div><div><span>Discount</span><strong>Rs. <?= number_format((float)$estimate['discount'],2) ?></strong></div><div><span>VAT (<?= number_format((float)$estimate['vat_rate'],2) ?>%)</span><strong>Rs. <?= number_format((float)$estimate['vat_amount'],2) ?></strong></div><div class="grand"><span>Total Amount</span><strong>Rs. <?= number_format((float)$estimate['total_amount'],2) ?></strong></div></div><?php if($estimate['notes']): ?><div class="section"><h3>Notes</h3><div class="notes"><?= nl2br(e($estimate['notes'])) ?></div></div><?php endif; ?><?php if($s['receipt_footer']): ?><footer class="footer"><?= nl2br(e($s['receipt_footer'])) ?></footer><?php endif; ?><footer class="footer powered-by-print"><?= e(powered_by_text()) ?></footer></main><script>window.addEventListener('load',function(){setTimeout(function(){window.print()},350)});</script></body></html>
